<?php
namespace Database\Seeders;
use App\Models\AccountMessage; use App\Models\User; use Illuminate\Database\Seeder;
class AccountMessageSeeder extends Seeder { public function run(): void { User::whereNotNull('project_id')->each(function($u){ if(AccountMessage::where('project_id',$u->project_id)->where('user_id',$u->id)->exists())return; foreach([['in','inbox','unread','Developer Support','Service Plan Upgrade Completed'],['in','inbox','read','Billing Department','Payment Receipt Available'],['in','inbox','read','Security Team','New Device Registered'],['out','sent','sent','Developer Support','Service Plan Question'],['out','sent','sent','Billing Support','Question About My Invoice'],['in','trash','read','Product Team','Old Feature Announcement']] as $i=>$row){[$dir,$folder,$status,$other,$subject]=$row;AccountMessage::create(['project_id'=>$u->project_id,'user_id'=>$u->id,'message_no'=>'MSG-'.strtoupper($dir).'-'.now()->format('Y').'-'.str_pad((string)(($u->id*100)+$i+1),4,'0',STR_PAD_LEFT),'direction'=>$dir,'folder'=>$folder,'status'=>$status,'from_name'=>$dir==='in'?$other:($u->company_name?:$u->name),'to_name'=>$dir==='in'?($u->company_name?:$u->name):$other,'subject'=>$subject,'message'=>"Hello,\n\nThis is a message from {$other}.\n\nThank you,\n{$other}",'sent_at'=>now()->subDays($i+1),'read_at'=>$status==='read'?now()->subDays($i+1):null,'deleted_at'=>$folder==='trash'?now()->subDay():null,'deleted_from'=>$folder==='trash'?'inbox':null]);}});}}
